use std::io::{self, Read};

fn input() -> Vec<String> {
    let mut s = String::new();
    io::stdin().read_to_string(&mut s).unwrap();
    s.split_whitespace().map(|t| t.to_string()).collect()
}

/// Make the two halves agree, element by element: wherever the left is
/// larger than the right, swap them. Both halves are parts of the SAME
/// buffer, so this needs one split rather than two borrows.
fn settle(v: &mut [i64]) -> usize {
    let mid = v.len() / 2;
    let (left, right) = v.split_at_mut(mid);
    let mut swaps = 0;
    for i in 0..left.len() {
        if left[i] > right[i] {
            std::mem::swap(&mut left[i], &mut right[i]);
            swaps += 1;
        }
    }
    swaps
}

fn show(label: &str, xs: &[i64]) {
    let parts: Vec<String> = xs.iter().map(|x| x.to_string()).collect();
    println!("{} {}", label, parts.join(" "));
}

fn main() {
    let t = input();
    if t.is_empty() {
        return;
    }
    let n: usize = t[0].parse().unwrap();
    let mut v: Vec<i64> = t[1..1 + n].iter().map(|s| s.parse().unwrap()).collect();

    if n % 2 != 0 {
        println!("odd");
        return;
    }

    let swaps = settle(&mut v);
    let mid = v.len() / 2;
    println!("swaps {}", swaps);
    show("left", &v[..mid]);
    show("right", &v[mid..]);
}
